"""Packaged read-only MSI/CFB controls using owned generated byte buffers."""
from __future__ import annotations

import argparse
import base64
import hashlib
import json
import os
from pathlib import Path
import struct
import subprocess

CORPUS_SHA256 = "dc0433a90bd660485401f22254788e0dbd0c6d1e555f88dc91776da766d05344"
FREE = 0xffffffff
END = 0xfffffffe


def sha256(raw):
    return hashlib.sha256(raw).hexdigest()


def controls(rows):
    positives = [{"name": row["name"], "raw": base64.b64decode(row["raw_base64"], validate=True), "expected": row, "error": None, "kind": "file"} for row in rows]
    mini = positives[0]["raw"]
    difat = next(row["raw"] for row in positives if row["name"] == "difat-v3")
    v4 = next(row["raw"] for row in positives if row["name"] == "mini-v4")
    cases = list(positives)

    def bad(name, raw, error="Static compound-file stream inspection failed", kind="file"):
        cases.append({"name": name, "raw": bytes(raw), "expected": None, "error": error, "kind": kind})

    for name, length in [("header-truncated", 511), ("minimum-sectors-truncated", 1024), ("last-sector-truncated", len(mini) - 1)]:
        bad(name, mini[:length])
    for name, offset, value, width in [
        ("signature-corrupt", 0, 0, 1),
        ("header-clsid-nonzero", 8, 1, 1),
        ("header-major-unsupported", 26, 5, 2),
        ("header-endianness", 28, 0, 2),
        ("header-sector-shift", 30, 11, 2),
        ("header-mini-sector-shift", 32, 5, 2),
        ("header-reserved", 34, 1, 1),
        ("v3-directory-count", 40, 1, 4),
        ("fat-count-overflow", 44, FREE, 4),
        ("directory-start-outside-file", 48, FREE, 4),
        ("mini-stream-cutoff", 56, 2048, 4),
        ("mini-fat-start-overlap", 60, 0, 4),
        ("mini-fat-count-overflow", 64, FREE, 4),
        ("difat-count-overflow", 72, FREE, 4),
        ("fat-marker-invalid", 512, END, 4),
        ("fat-root-cycle", 512 + 3 * 4, 3, 4),
        ("fat-link-outside-file", 512 + 3 * 4, 1000, 4),
        ("fat-padding-not-free", 512 + 4 * 4, 3, 4),
        ("root-type-invalid", 1024 + 66, 2, 1),
        ("directory-root-cycle", 1024 + 76, 0, 4),
        ("directory-unreachable-allocation", 1024 + 76, FREE, 4),
        ("root-mini-stream-overlap", 1024 + 116, 1, 4),
        ("v3-size-high-word", 1024 + 120, 1 << 32, 8),
        ("mini-stream-size-unaligned", 1024 + 120, 191, 8),
        ("directory-storage-cycle", 1024 + 128 + 76, 1, 4),
        ("name-invalid-utf16", 1024 + 256, 0xd800, 2),
        ("name-reserved-slash", 1024 + 256, ord('/'), 2),
        ("name-terminator-corrupt", 1024 + 256 + 14, 1, 2),
        ("name-length-odd", 1024 + 256 + 64, 15, 2),
        ("directory-color-invalid", 1024 + 256 + 67, 2, 1),
        ("stream-has-child", 1024 + 256 + 76, 3, 4),
        ("directory-sibling-cycle", 1024 + 384 + 72, 1, 4),
        ("mini-stream-allocation-shared", 1024 + 384 + 116, 0, 4),
        ("mini-fat-self-cycle", 1536, 0, 4),
        ("mini-fat-outside-root", 1536, 9, 4),
        ("mini-fat-padding-allocation", 1536 + 3 * 4, 0, 4),
    ]:
        mutated = bytearray(mini)
        struct.pack_into({1: '<B', 2: '<H', 4: '<I', 8: '<Q'}[width], mutated, offset, value)
        bad(name, mutated)
    for name, offset, value in [("difat-next-cycle", 113 * 512 - 4, 111), ("difat-duplicate-fat-sector", 112 * 512, 0), ("difat-allocation-marker", 512 + 111 * 4, END)]:
        mutated = bytearray(difat); struct.pack_into('<I', mutated, offset, value)
        bad(name, mutated)
    mutated = bytearray(v4); mutated[512] = 1
    bad("v4-header-padding-nonzero", mutated)
    mutated = bytearray(v4); struct.pack_into('<I', mutated, 40, 2)
    bad("v4-directory-count-mismatch", mutated)
    bad("input-hardlink-rejected", mini, "MSI input could not be safely read", "hardlink")
    bad("input-directory-rejected", b"", "MSI input could not be safely read", "directory")
    bad("input-missing-rejected", b"", "MSI input could not be safely read", "missing")
    return cases


def snapshot(root):
    result = {}
    for path in sorted(root.rglob('*')):
        relative = str(path.relative_to(root))
        if path.is_dir():
            result[relative] = {"type": "directory"}
        elif path.is_file():
            result[relative] = {"type": "file", "bytes": path.stat().st_size, "sha256": sha256(path.read_bytes())}
    return result


def verify_metadata(result, reference):
    assert result['format'] == 'msi'
    assert result['inspection'] == 'static_streams'
    for key in ['version', 'sector_size', 'stream_bytes_read']:
        assert result[key] == reference[key], key
    assert result['stream_count'] == len(reference['streams'])
    assert result['omissions'] == []
    assert len(result['streams']) == len(reference['streams'])
    for actual, expected in zip(result['streams'], reference['streams']):
        for key in ['path', 'name', 'size', 'sha256']:
            assert actual[key] == expected[key], (key, actual, expected)
        assert actual['type'] == ('cabinet' if expected['cabinet'] else 'data')
        assert 'data' not in actual and 'data_base64' not in actual and 'raw' not in actual
    assert any('not executed' in s for s in result['limitations'])
    assert any('not unpacked' in s for s in result['limitations'])


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--bundle', required=True)
    parser.add_argument('--output-root', required=True)
    parser.add_argument('--corpus', default='output/rust-msi-reference-corpus.json')
    args = parser.parse_args()
    corpus_raw = Path(args.corpus).read_bytes()
    assert len(corpus_raw) <= 256 * 1024 and sha256(corpus_raw) == CORPUS_SHA256, 'Generated corpus identity changed'
    corpus = json.loads(corpus_raw)
    assert len(corpus['rows']) == 5
    for row in corpus['rows']:
        assert sha256(base64.b64decode(row['raw_base64'], validate=True)) == row['sha256']
        for stream in row['streams']:
            data = base64.b64decode(stream['data_base64'], validate=True)
            assert len(data) == stream['size'] and sha256(data) == stream['sha256']
    exe = Path(args.bundle).resolve() / 'emumee-rs.exe'
    assert exe.is_file(), 'Packaged controller executable missing'
    root = Path(args.output_root).resolve()
    root.mkdir(exist_ok=False)
    (root / 'verifier-input.json').write_text(json.dumps({'corpus_sha256': CORPUS_SHA256, 'controller_sha256': sha256(exe.read_bytes()), 'scope': 'Owned generated CFB buffers; read-only CLI; no worker or sample execution'}, indent=2) + '\n', encoding='utf-8')
    records = []
    creationflags = subprocess.CREATE_NO_WINDOW if os.name == 'nt' else 0
    for index, case in enumerate(controls(corpus['rows'])):
        case_root = root / case['name']
        case_root.mkdir()
        # Rotate supported family suffixes; parsing remains static signature-based.
        path = case_root / ('input' + ['.msi', '.msp', '.mst'][index % 3])
        if case['kind'] == 'directory':
            path.mkdir()
        elif case['kind'] != 'missing':
            path.write_bytes(case['raw'])
            if case['kind'] == 'hardlink':
                (case_root / 'owned-hardlink-copy').hardlink_to(path)
        before = snapshot(case_root)
        actual_exit = None
        try:
            process = subprocess.run([str(exe), 'inspect-msi', str(path)], capture_output=True, check=False, timeout=60, creationflags=creationflags)
            actual_exit = process.returncode
            (case_root / 'stdout.txt').write_bytes(process.stdout)
            (case_root / 'stderr.txt').write_bytes(process.stderr)
            after = snapshot(case_root); after.pop('stdout.txt', None); after.pop('stderr.txt', None)
            assert before == after, 'Read-only inspection changed input files or extracted host artifacts'
            accepted = case['expected'] is not None
            assert actual_exit == (0 if accepted else 2), (actual_exit, process.stderr.decode('utf-8', errors='replace'))
            if accepted:
                verify_metadata(json.loads(process.stdout), case['expected'])
            else:
                assert case['error'] in process.stderr.decode('utf-8', errors='replace'), case['error']
            records.append({'case': case['name'], 'accepted': accepted, 'exit': actual_exit, 'source_unchanged': True, 'no_host_extraction': True, 'verified': True})
        except Exception as error:
            records.append({'case': case['name'], 'exit': actual_exit, 'verified': False, 'error': str(error)})
            (root / 'verification.json').write_text(json.dumps(records, indent=2) + '\n', encoding='utf-8')
            raise
        (root / 'verification.json').write_text(json.dumps(records, indent=2) + '\n', encoding='utf-8')
    print(f'Verified {len(records)} generated read-only MSI/CFB stream/reference/corruption/file-boundary controls; no worker or sample execution.')


if __name__ == '__main__':
    main()
